-- EXECUTED regression fixture for nestly_v723 — CI-100 check 92 (UI/RPC contract validation).
--
-- WHY. docs/qa/CI-100-CHECKLIST.md check 92 requires "Generated TypeScript/JSON schemas or
-- integration tests prove every UI field matches the server payload." Nothing before this
-- migration wrote down, in one machine-readable place, which top-level keys each of the 25
-- public.get_ci_* readers (plus get_customer_intelligence_v83 and app.v176_evidence_pack) is
-- contractually required to emit. docs/design/ci/CI-READER-CONTRACTS.json is that contract,
-- generated by scripts/quality/ci-reader-contracts.mjs; this fixture is the SQL half of proving
-- it — it calls every one of the 27 readers against a DELIBERATELY MINIMAL, entitled, operational
-- business (six clients, six same-branch sales, no consents, no packages, no discounts, no
-- loyalty programme, no discovery scan — BELOW every evidence floor this codebase has) and
-- asserts every declared top-level key exists on the real payload with the declared
-- jsonb_typeof(), naming the reader and the key on failure.
--
-- The nested "which keys does a page RENDERER read" half of check 92 is proven on the JS side
-- (tests/business-ui/v723-ci-reader-contracts.test.mjs, tests/platform-console/v723-ci-reader-
-- contracts.test.mjs) — a SQL fixture has no access to app/app.js's renderer source, and the JS
-- side already has the exact regex-extraction machinery nestly_v667's
-- tests/platform-console/v667-consultative-payload.test.mjs pioneered for this. This file proves
-- the TOP-LEVEL contract only, which is also the half a minimal fixture can prove honestly:
-- nested UI-read paths (e.g. ranked[].impact.expected_value.inputs.scored) are frequently null or
-- absent-by-design below the evidence floor this fixture deliberately sits under, so asserting
-- their PRESENCE here would either force the fixture to manufacture unrealistic richness or make
-- the assertion vacuously permissive — see docs/qa/CI-CORPUS-FIXTURE-GUIDE.md's "predetermined
-- truth tables" rule and "assert your preconditions" rule, both of which a nested-below-floor
-- assertion here would violate one way or the other.
--
-- CONTRACT SOURCE. The JSON embedded below (between the CI-READER-CONTRACTS-EMBED markers) is
-- NOT hand-written — it is generated, byte-for-byte from the same CONTRACTS object, alongside
-- docs/design/ci/CI-READER-CONTRACTS.json, by scripts/quality/ci-reader-contracts.mjs. A test
-- (tests/business-ui/v723-ci-reader-contracts.test.mjs) parses both and asserts they are deeply
-- equal, so this file can only drift from the JSON file by someone hand-editing between the
-- markers, which that test would catch. The db-tests harness runs this file through plain
-- `psql -f` against an ephemeral cluster with no filesystem grant for `\set` + `pg_read_file`
-- (see the fixture guide), so embedding the literal is the only way this SQL session can read
-- the contract at all.
--
-- Named for v723: every top-level-key/type assertion must FAIL against a reader whose emitted
-- keys or types have drifted from the contract. One transaction, rolled back. No production
-- access.

\set ON_ERROR_STOP on

begin;

create temp table _fail(k text, v text) on commit drop;
create temp table _payloads(fn text primary key, payload jsonb) on commit drop;

do $v723$
declare
  biz        uuid := '00000000-0000-4000-8000-0000000c1001';
  br1        uuid := '00000000-0000-4000-8000-0000000c1011';
  u_sa       uuid := '00000000-0000-4000-8000-0000000c1101';
  u_owner    uuid := '00000000-0000-4000-8000-0000000c1102';
  svc1       uuid := '00000000-0000-4000-8000-0000000c1301';
  svc2       uuid := '00000000-0000-4000-8000-0000000c1302';
  node1      text;
  node2      text;
  cl1        uuid := '00000000-0000-4000-8000-0000000c1401';
  cl2        uuid := '00000000-0000-4000-8000-0000000c1402';
  cl3        uuid := '00000000-0000-4000-8000-0000000c1403';
  cl4        uuid := '00000000-0000-4000-8000-0000000c1404';
  cl5        uuid := '00000000-0000-4000-8000-0000000c1405';
  cl6        uuid := '00000000-0000-4000-8000-0000000c1406';
  shadow_run uuid := '00000000-0000-4000-8000-0000000c1901';
  d_from     date := current_date - 32;
  d_to       date := current_date;
begin
  ---------------------------------------------------------------------------
  -- actors: an operational, entitled firm + a super admin (Google-SSO claims — see the fixture
  -- guide: app.is_super_admin() requires the amr/app_metadata shape, not just a super_admins row)
  ---------------------------------------------------------------------------
  insert into auth.users (id, email) values
    (u_sa,'zz-v723-sa@example.test'), (u_owner,'zz-v723-owner@example.test')
    on conflict (id) do nothing;
  insert into public.super_admins (user_id, email)
    values (u_sa,'zz-v723-sa@example.test') on conflict do nothing;

  insert into public.businesses (id, name, slug, enabled_modules, industry) values
    (biz,'ZZ v723 corpus','zz-v723-corpus',
      array['dashboard','clients','sales','reports','customerintel'],'salon')
    on conflict (id) do nothing;
  insert into public.branches (id, business_id, name, is_default, active) values
    (br1, biz, 'ZZ v723 main', true, true)
    on conflict (id) do nothing;
  insert into public.staff (business_id, user_id, role, full_name, active, access_state) values
    (biz, u_owner, 'owner', 'ZZ v723 owner', true, 'approved')
    on conflict do nothing;

  insert into public.business_workspace_controls_v94
    (business_id, approval_status, decided_at, decision_reason)
  values (biz, 'approved', now(), 'v723 reader-contracts fixture')
    on conflict (business_id) do update
      set approval_status='approved', decided_at=now(), decision_reason='v723 reader-contracts fixture';
  insert into public.business_subscription_lifecycle_v94 (business_id, state, workspace_paused)
  values (biz, 'current', false)
    on conflict (business_id) do update set state='current', workspace_paused=false;
  insert into public.subscriptions (business_id, status, payment_status, current_period_end)
  values (biz, 'active', 'paid', now() + interval '30 days')
    on conflict (business_id) do update set status='active', payment_status='paid';

  ---------------------------------------------------------------------------
  -- MINIMAL catalogue + customers + sales — deliberately below every evidence floor
  ---------------------------------------------------------------------------
  select n.node_key into node1 from public.taxonomy_nodes n
   where n.version_no=1 and n.level=2 order by n.node_key limit 1;
  select n.node_key into node2 from public.taxonomy_nodes n
   where n.version_no=1 and n.level=2 and n.node_key<>node1 order by n.node_key limit 1;
  if node1 is null or node2 is null then
    insert into _fail values ('B0','taxonomy v1 has fewer than two level-2 nodes; fixture cannot run');
    return;
  end if;

  insert into public.services (id, business_id, name, price_cents, duration_min) values
    (svc1, biz, 'ZZ v723 svc one', 5000, 30),
    (svc2, biz, 'ZZ v723 svc two', 8000, 45)
    on conflict (id) do nothing;
  insert into public.service_canonical_map (business_id, service_id, node_key, version_no, method, mapped_by) values
    (biz, svc1, node1, 1, 'owner_chosen', u_owner),
    (biz, svc2, node2, 1, 'owner_chosen', u_owner)
    on conflict do nothing;

  insert into public.clients (id, business_id, full_name, birth_date, gender) values
    (cl1, biz, 'ZZ v723 Client One', '1990-05-01', 'female'),
    (cl2, biz, 'ZZ v723 Client Two', '1985-02-10', 'male'),
    (cl3, biz, 'ZZ v723 Client Three', '1975-09-20', 'female'),
    (cl4, biz, 'ZZ v723 Client Four', '1998-11-11', 'male'),
    (cl5, biz, 'ZZ v723 Client Five', '2001-03-03', 'other'),
    (cl6, biz, 'ZZ v723 Client Six', '1988-07-07', 'female')
    on conflict (id) do nothing;

  insert into public.sales (id, business_id, branch_id, client_id, kind, amount_cents,
                            occurred_at, counts_as_revenue, counts_as_visit)
  select gen_random_uuid(), biz, br1, c.c_id, 'service', 5000 + (row_number() over())*500,
         (current_date - (row_number() over())::int)::timestamp at time zone 'Asia/Singapore', true, true
    from (values (cl1),(cl2),(cl3),(cl4),(cl5),(cl6)) as c(c_id)
   on conflict do nothing;

  insert into public.sale_items (business_id, sale_id, item_type, ref_id, qty, unit_cents, line_cents)
  select s.business_id, s.id, 'service', case when s.client_id in (cl1,cl2,cl3) then svc1 else svc2 end,
         1, s.amount_cents, s.amount_cents
    from public.sales s where s.business_id=biz;

  -- one shadow-reconciliation run, matching what the independent oracle inside
  -- get_ci_shadow_reconciliation_v685 will recompute from the sales rows above (6 sales,
  -- 5000+500..3000 = 33000 cents; matches to keep overall_status = 'PASS', which is not itself
  -- asserted here — only the top-level shape is).
  insert into app.ci_shadow_runs_v685 (id, business_id, window_from, window_to, payload)
  values (
    shadow_run, biz, d_from, d_to,
    jsonb_build_object(
      'window', jsonb_build_object('from', d_from, 'to', d_to),
      'as_of', now()::text,
      'get_revenue_truth_v106', jsonb_build_object(
        'totals', jsonb_build_object(
          'known_revenue_minor', (select coalesce(sum(amount_cents),0) from public.sales where business_id=biz),
          'completed_transactions', (select count(*) from public.sales where business_id=biz)
        )
      )
    )
  ) on conflict (id) do nothing;

  ---------------------------------------------------------------------------
  -- call every reader as the entitled owner (super-admin claims set separately for the one
  -- reader that requires it)
  ---------------------------------------------------------------------------
  perform set_config('request.jwt.claims',
    json_build_object('sub', u_owner, 'role', 'authenticated')::text, true);

  insert into _payloads values
    ('public.get_ci_acquisition_v1', public.get_ci_acquisition_v1(biz, d_from, d_to, null, now())),
    ('public.get_ci_category_customers_v1', public.get_ci_category_customers_v1(biz, node1, d_from, d_to, 50, null, now())),
    ('public.get_ci_category_mix_v1', public.get_ci_category_mix_v1(biz, d_from, d_to, null, now())),
    ('public.get_ci_contactability_v1', public.get_ci_contactability_v1(biz, null, now())),
    ('public.get_ci_customer_records_v1', public.get_ci_customer_records_v1(biz, cl1, d_from, d_to, null, now())),
    ('public.get_ci_daypart_v1', public.get_ci_daypart_v1(biz, d_from, d_to, null, now())),
    ('public.get_ci_demographic_cohort_v1', public.get_ci_demographic_cohort_v1(biz, 'female', 20, 60, node1, d_from, d_to, 30, null, now())),
    ('public.get_ci_demographic_preference_v1', public.get_ci_demographic_preference_v1(biz, d_from, d_to, null, now())),
    ('public.get_ci_demographics_v1', public.get_ci_demographics_v1(biz, d_from, d_to, null, now())),
    ('public.get_ci_dictionary_v1', public.get_ci_dictionary_v1()),
    ('public.get_ci_discount_dependency_v1', public.get_ci_discount_dependency_v1(biz, d_from, d_to, null, now())),
    ('public.get_ci_discovery_v1', public.get_ci_discovery_v1(biz, d_from, d_to, null, now())),
    ('public.get_ci_engagement_v1', public.get_ci_engagement_v1(biz, 3, null, now())),
    ('public.get_ci_funnel_conversion_v1', public.get_ci_funnel_conversion_v1(biz, d_from, d_to, 60, null, now())),
    ('public.get_ci_funnel_v1', public.get_ci_funnel_v1(biz, d_from, d_to, null, now())),
    ('public.get_ci_loyalty_programmes_v1', public.get_ci_loyalty_programmes_v1(biz, d_from, d_to, null)),
    ('public.get_ci_marketing_funnel_v1', public.get_ci_marketing_funnel_v1(biz, d_from, d_to, null, now())),
    ('public.get_ci_opportunities_v1', public.get_ci_opportunities_v1(biz, d_from, d_to, null, now(), true)),
    ('public.get_ci_package_intelligence_v1', public.get_ci_package_intelligence_v1(biz, d_from, d_to, null, now())),
    ('public.get_ci_rebooking_v1', public.get_ci_rebooking_v1(biz, d_from, d_to, null)),
    ('public.get_ci_retention_windows_v1', public.get_ci_retention_windows_v1(biz, d_from, d_to, null, now())),
    ('public.get_ci_service_intelligence_v1', public.get_ci_service_intelligence_v1(biz, d_from, d_to, null, now())),
    ('public.get_ci_staff_identity_v1', public.get_ci_staff_identity_v1(biz, d_from, d_to, null)),
    ('public.get_ci_staff_performance_v1', public.get_ci_staff_performance_v1(biz, d_from, d_to, null, now())),
    ('public.get_customer_intelligence_v83', public.get_customer_intelligence_v83(biz, null, d_from, d_to, 20, null, null, null));

  -- get_ci_shadow_reconciliation_v685 AND app.v176_evidence_pack are both platform/consultant-
  -- only (app.is_super_admin() / app.v176_can_read_firm_report -> app.is_super_admin() OR
  -- app.platform_firm_report_access_v94) — nestly_v720 tightened v176_evidence_pack from "any
  -- entitled owner" to this, so both calls need the Google-SSO claim shape, not the owner
  -- session the rest of the batch used (see the fixture guide's "Impersonation" section).
  perform set_config('request.jwt.claims', json_build_object(
      'sub', u_sa, 'role', 'authenticated',
      'amr', json_build_array(json_build_object('method','oauth')),
      'app_metadata', json_build_object('providers', json_build_array('google'))
    )::text, true);
  insert into _payloads values
    ('public.get_ci_shadow_reconciliation_v685', public.get_ci_shadow_reconciliation_v685(biz, shadow_run)),
    ('app.v176_evidence_pack', app.v176_evidence_pack(biz, 'monthly', (date_trunc('month', d_to))::date, d_to));
end
$v723$;

