  contracts_json text := $circ723${"$schema":"CI-READER-CONTRACTS v1 — see docs/qa/CI-100-CHECKLIST.md check 92","generated_by":"scripts/quality/ci-reader-contracts.mjs","readers":{"public.get_ci_acquisition_v1":{"version":"nestly_v717","required":{"as_of":"string","period":"object","sources":"array","trace_id":"string","exclusions":"object","time_basis":"string","generated_at":"string","observed_since":"string"},"nested":{"sources.*.via":"string","sources.*.evidence":"string","sources.*.customers":"number","sources.*.new_in_period":"number","sources.*.repeat_customers":"number","observed_since":"string"}},"public.get_ci_funnel_v1":{"version":"nestly_v717","required":{"as_of":"string","period":"object","funnel":"object","trace_id":"string","exclusions":"object","time_basis":"string","generated_at":"string","observed_since":"string"},"nested":{"funnel":"object","funnel.join":"object","funnel.join.page_view":"number|null","funnel.join.started":"number|null","funnel.join.completed":"number|null","funnel.booking":"object","funnel.booking.page_view":"number|null","funnel.booking.started":"number|null","funnel.booking.completed":"number|null","observed_since":"string","__optional":["funnel.join","funnel.join.page_view","funnel.join.started","funnel.join.completed","funnel.booking","funnel.booking.page_view","funnel.booking.started","funnel.booking.completed"]}},"public.get_ci_contactability_v1":{"version":"nestly_v717","required":{"as_of":"string","period":"object","business_offers":"object","rewards_and_points":"object","exclusions":"object","time_basis":"string","generated_at":"string","trace_id":"string","note":"string"},"nested":{"business_offers.category":"string","business_offers.customers":"number","business_offers.allowed_by_channel":"object","business_offers.allowed_by_channel.whatsapp":"number","business_offers.allowed_by_channel.sms":"number","business_offers.allowed_by_channel.email":"number","business_offers.allowed_by_channel.push":"number","business_offers.