ic.get_ci_staff_performance_v1":{"version":"nestly_v699","nested":{},"required":{"as_of":"string","comparisons":"object","exclusions":"object","generated_at":"string","note":"string","period":"object","scope":"object","staff":"array","time_basis":"string","trace_id":"string","visit_definition":"string"}},"app.v176_evidence_pack":{"version":"nestly_v713","nested":{},"required":{"contract_version":"string","generated_at":"string","timezone":"string","currency":"string","scope":"object","sales":"object","insights":"object","account_opens":"object","consultant_brief":"object|null","catalogue_affinity":"object|null","recommendations":"object|null","findings":"object","evidence_completeness":"object"}}}}$circ723$;
  -- CI-READER-CONTRACTS-EMBED-END

  doc         jsonb;
  readers     jsonb;
  reader_name text;
  reader_def  jsonb;
  required    jsonb;
  req_key     text;
  req_type    text;
  payload     jsonb;
  allowed     text[];
  actual_type text;
begin
  doc := contracts_json::jsonb;
  readers := doc->'readers';
  if readers is null or jsonb_typeof(readers) <> 'object' then
    insert into _fail values ('embed', 'embedded contract JSON has no top-level "readers" object');
  else
    for reader_name, reader_def in select * from jsonb_each(readers) loop
      select p.payload into payload from _payloads p where p.fn = reader_name;
      if payload is null and not exists (select 1 from _payloads p where p.fn = reader_name) then
        insert into _fail values (reader_name, 'contract declares this reader but the fixture never called it');
        continue;
      end if;

      required := reader_def->'required';
      if required is null or jsonb_typeof(required) <> 'object' then
        insert into _fail values (reader_name, 'contract entry has no "required" object');
        continue;
      end if;

      for req_key in select jsonb_object_keys(required) loop
        req_type := required->>req_key;
        allowed := string_to_array(req_type, '|');
        if not (payload ? req_key) then
          insert into _fail values (reader_name, format('missing required top-level key "%s"', req_key));
          continue;
        end if;
        actual_type := jsonb_typeof(payload->req_key);
        if not (actual_type = any(allowed)) then
          insert into _fail values (reader_name,
            format('key "%s" has type "%s", contract declares "%s"', req_key, actual_type, req_type));
        end if;
      end loop;
    end loop;
  end if;

  -- The reverse direction: every payload this fixture captured must be declared in the
  -- contract, or the contract is incomplete rather than the reader being non-compliant.
  for reader_name in select fn from _payloads loop
    if not (readers ? reader_name) then
      insert into _fail values (reader_name, 'fixture called this reader but the contract does not declare it');
    end if;
  end loop;
end
$assert$;

select case when count(*)=0 then 'PASS — every declared top-level key/type held against the minimal corpus'
       else 'FAIL' end as verdict,
       count(*) as failures from _fail;
select k, v from _fail order by k, v;

do $verdict$
declare n integer; d text;
begin
  select count(*), string_agg(format('%s: %s', f.k, f.v), E'\n  ' order by f.k, f.v)
    into n, d from _fail f;
  if n > 0 then raise exception 'v723: % contract assertion(s) failed:%  %', n, E'\n', d; end if;
end
$verdict$;

rollback;
